// Diagnostic only: replay recorded inputs, never regenerate positions from replies.
#include "uci_process.hpp"
#include "softnodes_labels.hpp"
#include "forge/search.hpp"
#include <fstream>
#include <iostream>
#include <memory>
#include <limits>

namespace {
using Clock=std::chrono::steady_clock;
std::string quote(const std::string&s){std::string out="\"";const char*h="0123456789abcdef";for(unsigned char c:s){if(c=='"'||c=='\\'){out+='\\';out+=char(c);}else if(c<32){out+="\\u00";out+=h[c>>4];out+=h[c&15];}else out+=char(c);}return out+'"';}
std::string hex_bytes(const std::string&s){std::string out;const char*h="0123456789abcdef";out.reserve(s.size()*2);for(unsigned char c:s){out+=h[c>>4];out+=h[c&15];}return out;}
void require(bool b,const std::string&s){if(!b)throw std::runtime_error(s);}
std::vector<std::string> lines(const std::string&file){std::ifstream in(file);require(bool(in),"input file unavailable: "+file);std::vector<std::string> out;std::string s;while(std::getline(in,s)){require(s.find('\r')==std::string::npos&&s.find('\0')==std::string::npos,"invalid input byte");out.push_back(s);}require(in.eof(),"input read failed");return out;}
std::vector<std::string> stdout_lines(const std::string&s){std::istringstream in(s);std::string line;std::vector<std::string> out;while(std::getline(in,line))if(line.rfind("< stdout ",0)==0)out.push_back(line.substr(9));return out;}
std::vector<std::string> stdin_lines(const std::string&s){std::istringstream in(s);std::string line;std::vector<std::string> out;while(std::getline(in,line))if(line.rfind("> stdin ",0)==0)out.push_back(line.substr(8));return out;}
bool diagnostic(const std::string&s){for(const char*p:{"AddressSanitizer","UndefinedBehaviorSanitizer","LeakSanitizer","ThreadSanitizer","MemorySanitizer","runtime error:","Sanitizer CHECK failed","terminate called"})if(s.find(p)!=std::string::npos)return true;return false;}
struct Row{std::size_t ordinal=0,source=0,first=0,last=0;int pair=0,half=0,ply=0,soft=0;std::string position,fen,go;std::vector<std::string> expected;};
struct Inputs{std::string kind;std::vector<std::string> commands;std::vector<Row> rows;};
Inputs load(const std::string&root,const std::string&kind){require(kind=="full"||kind=="cold","kind must be full or cold");Inputs d;d.kind=kind;d.commands=lines(root+'/'+kind+".commands.txt");const auto f=lines(root+'/'+kind+".frames.txt");std::size_t i=0;while(i<f.size()){Row r;std::string prefix,extra;std::istringstream h(f[i++]);require(bool(h>>prefix>>r.ordinal>>r.source>>r.first>>r.last>>r.pair>>r.half>>r.ply>>r.soft)&&prefix=="ROW"&&!(h>>extra),"malformed frame header");require(i+4<=f.size(),"short frame");r.position=f[i++];r.fen=f[i++];r.go=f[i++];std::uint64_t n=0;require(decimal_nodes(f[i++],n)&&n<=10000&&i+n<=f.size(),"malformed frame output size");r.expected.assign(f.begin()+i,f.begin()+i+n);i+=n;require(r.ordinal==d.rows.size()+1&&r.first>=1&&r.last==r.first+2&&r.last<=d.commands.size(),"frame order/bounds");require(d.commands[r.first-1]==r.position&&d.commands[r.first]==r.go&&d.commands[r.last-1]=="isready","frame command alignment");require(r.soft==0||r.soft==1,"frame mode");require(r.go==(r.soft?"go softnodes 2500":"go nodes 2000"),"unexpected go");d.rows.push_back(std::move(r));}
 const std::vector<std::string> prefix={"uci","setoption name Threads value 1","setoption name Hash value 16","setoption name OwnBook value false","isready","setoption name HindsightDepth value false","setoption name MateAlphaGuard value false","isready"};require(d.commands.size()>=prefix.size()&&std::equal(prefix.begin(),prefix.end(),d.commands.begin()),"startup command mismatch");require(d.commands.back()=="quit","final quit missing");require(d.commands.size()==(kind=="full"?24994:14)&&d.rows.size()==(kind=="full"?8291:1),"declared input count mismatch");return d;
}
struct Oracle{forge::Board board;std::vector<std::string> history;void reset(){require(board.set_fen(forge::Board::StandardStartFen),"oracle reset");history.clear();}void position(const Row&r){std::istringstream in(r.position);std::string token;for(const char*x:{"position","startpos","moves"})require(bool(in>>token)&&token==x,"recorded position prefix");std::vector<std::string> moves;while(in>>token)moves.push_back(token);require(moves.size()>=history.size()&&std::equal(history.begin(),history.end(),moves.begin()),"recorded history lost prefix");for(std::size_t i=history.size();i<moves.size();++i){const auto legal=board.legal_moves();auto it=std::find_if(legal.begin(),legal.end(),[&](const auto&m){return forge::Board::move_to_uci(m)==moves[i];});require(it!=legal.end(),"illegal recorded history move");forge::Undo u;require(board.make_move(*it,u),"oracle history rejected");}history=std::move(moves);require(board.fen()==r.fen,"recorded FEN mismatch");require(!board.legal_moves().empty(),"unexpected terminal search position");}};
LabelCheck validate(const std::vector<std::string>&out,const Row&r,Oracle&oracle){const auto c=check_labels(out,r.soft==1,1);require(c.error.empty(),"label parser: "+c.error);if(r.soft){require(c.item2,"softnodes_item2_line_count_or_order");require(c.item3,"softnodes_item3_label_move");require(c.item4,"softnodes_item4_iteration_nodes");}const int score=r.soft?c.score:c.last_score_value;require(score>=-forge::MateValue&&score<=forge::MateValue,"score_out_of_range");const auto legal=oracle.board.legal_moves();require(std::any_of(legal.begin(),legal.end(),[&](const auto&m){return forge::Board::move_to_uci(m)==c.bestmove;}),c.bestmove.empty()||c.bestmove=="0000"?"missing_move":"illegal_move");return c;}
std::string last_score_kind(const LabelCheck&r){std::istringstream in(r.last_score_line);std::string s,k;while(in>>s)if(s=="score"){in>>k;return k;}return "";}
bool same_tuple(const LabelCheck&a,const LabelCheck&b,bool soft){return a.bestmove==b.bestmove&&a.exact==b.exact&&a.kind==b.kind&&a.score==b.score&&a.depth==b.depth&&a.has_depth==b.has_depth&&a.nodes==b.nodes&&a.has_nodes==b.has_nodes&&a.any_score==b.any_score&&a.last_score_value==b.last_score_value&&last_score_kind(a)==last_score_kind(b)&&(!soft||(a.x_valid==b.x_valid&&a.x==b.x));}
std::string tuple(const LabelCheck&r){return "{\"bestmove\":"+quote(r.bestmove)+",\"exact\":"+std::to_string(r.exact)+",\"kind\":"+quote(r.kind)+",\"score\":"+std::to_string(r.score)+",\"depth\":"+std::to_string(r.depth)+",\"nodes\":"+std::to_string(r.nodes)+",\"last_score_kind\":"+quote(last_score_kind(r))+",\"last_score\":"+std::to_string(r.last_score_value)+",\"soft_x\":"+(r.x_valid?std::to_string(r.x):"null")+"}";}
void unit(){Oracle oracle;oracle.reset();Row r;r.position="position startpos moves";r.fen=forge::Board::StandardStartFen;r.go="go nodes 2000";oracle.position(r);int count=0;auto test=[&](const char*name,const auto&f){f();++count;std::cout<<"PASS "<<name<<'\n';};auto rejects=[&](const std::vector<std::string>&v,Row row){bool failed=false;try{validate(v,row,oracle);}catch(const std::exception&){failed=true;}require(failed,"negative fixture accepted");};const std::vector<std::string> good={"info depth 4 score cp 10 nodes 2000 time 3 pv e2e4","bestmove e2e4","readyok"};const auto base=validate(good,r,oracle);
 test("ordinary legal completion",[&]{require(base.bestmove=="e2e4","move");});test("missing bestmove rejected",[&]{rejects({good[0],"readyok"},r);});test("illegal bestmove rejected",[&]{rejects({good[0],"bestmove e2e5","readyok"},r);});test("out-of-range score rejected",[&]{rejects({"info depth 4 score cp 999999 nodes 2000 pv e2e4","bestmove e2e4"},r);});test("ordinary soft label rejected",[&]{rejects({good[0],"info string softnodes nodes 3000","bestmove e2e4"},r);});
 Row soft=r;soft.soft=1;soft.go="go softnodes 2500";const std::vector<std::string> sg={"info depth 4 score cp 10 nodes 3000 time 3 pv e2e4","info string softnodes nodes 3100","bestmove e2e4","readyok"};const auto sb=validate(sg,soft,oracle);test("soft valid label",[&]{require(sb.item2&&sb.item3&&sb.item4,"soft labels");});test("soft missing X rejected",[&]{rejects({sg[0],"bestmove e2e4"},soft);});test("soft returned PV mismatch rejected",[&]{rejects({sg[0],sg[1],"bestmove d2d4"},soft);});test("soft insufficient iteration rejected",[&]{rejects({"info depth 4 score cp 10 nodes 2000 pv e2e4","info string softnodes nodes 2400","bestmove e2e4"},soft);});
 test("time nps hashfull excluded from stable tuple",[&]{const auto c=validate({"info depth 4 score cp 10 nodes 2000 time 999 nps 2 hashfull 99 pv e2e4","bestmove e2e4"},r,oracle);require(same_tuple(base,c,false),"volatile fields affected tuple");});test("nodes change detected",[&]{auto c=base;c.nodes++;require(!same_tuple(base,c,false),"node drift missed");});test("soft X change detected",[&]{auto c=sb;c.x++;require(!same_tuple(sb,c,true),"X drift missed");});test("last score kind change detected",[&]{auto c=base;c.last_score_line="info depth 5 score mate 10 lowerbound nodes 2010";require(!same_tuple(base,c,false),"kind drift missed");});test("illegal recorded history rejected",[&]{Oracle o;o.reset();Row bad=r;bad.position+=" e2e5";bool fail=false;try{o.position(bad);}catch(const std::exception&){fail=true;}require(fail,"bad history accepted");});std::cout<<"UNIT {\"checks\":"<<count<<",\"engine_runs\":0}"<<std::endl;}
int remaining(Clock::time_point end){const auto n=std::chrono::duration_cast<std::chrono::milliseconds>(end-Clock::now()).count();require(n>0,"replay_or_search_deadline");return int(std::min<std::int64_t>(15000,n));}
void offline(const Inputs&d){Oracle oracle;oracle.reset();std::size_t index=0,checked=0;for(std::size_t i=0;i<d.commands.size();++i){const auto&cmd=d.commands[i];if(cmd=="ucinewgame")oracle.reset();if(cmd.rfind("position ",0)==0){require(index<d.rows.size(),"too many positions");const auto&r=d.rows[index++];require(r.first==i+1,"offline input ordinal");oracle.position(r);const auto c=validate(r.expected,r,oracle);require(same_tuple(c,c,r.soft),"tuple selfcheck");++checked;}}require(checked==d.rows.size(),"offline missing positions");std::cout<<"OFFLINE {\"kind\":"<<quote(d.kind)<<",\"commands\":"<<d.commands.size()<<",\"searches\":"<<checked<<",\"legal_histories_and_expected_moves\":"<<checked<<",\"label_checks\":"<<checked<<",\"engine_runs\":0}"<<std::endl;}
void verify_trace(const Inputs&d,const std::string&file){Oracle oracle;oracle.reset();const Row*active=nullptr;std::vector<std::string> commands,out;std::size_t index=0,completed=0,matched=0;bool frozen=false,go=false,best=false,barrier=false,drifted=false;for(const auto&line:lines(file)){
 if(line.rfind("EVENT {\"event\":\"pre_quit_completion_frozen\"",0)==0)frozen=true;
 if(line.rfind("> stdin ",0)==0){const auto cmd=line.substr(8);commands.push_back(cmd);if(cmd=="quit"){frozen=true;continue;}require(!frozen,"input after completion snapshot");require(!drifted||d.kind=="cold","input after stop-first tuple drift");require(commands.size()<=d.commands.size()&&cmd==d.commands[commands.size()-1],"trace input prefix differs");if(cmd=="ucinewgame"){require(!active,"trace reset during search");oracle.reset();}if(cmd.rfind("position ",0)==0){require(!active&&index<d.rows.size(),"trace position order");active=&d.rows[index++];require(active->first==commands.size(),"trace position ordinal");oracle.position(*active);out.clear();go=best=barrier=false;}if(cmd.rfind("go ",0)==0){require(active&&cmd==active->go&&!go,"trace go order");go=true;}if(cmd=="isready"&&active){require(go&&best&&!barrier,"trace barrier order");barrier=true;}}
 if(line.rfind("< stdout ",0)==0&&active&&!frozen){const auto value=line.substr(9);out.push_back(value);if(value.rfind("bestmove",0)==0){require(go&&!best,"trace duplicate/early bestmove");best=true;}if(value=="readyok"){require(barrier,"trace early readyok");const auto a=validate(out,*active,oracle),e=validate(active->expected,*active,oracle);++completed;if(same_tuple(a,e,active->soft))++matched;else drifted=true;active=nullptr;}}
 }
 require(commands.empty()||commands.back()=="quit","trace missing quit");std::cout<<"TRACE_VERIFY {\"kind\":"<<quote(d.kind)<<",\"commands\":"<<commands.size()<<",\"completed_searches_before_quit\":"<<completed<<",\"matched_searches\":"<<matched<<",\"exact_full_sequence\":"<<(commands==d.commands?"true":"false")<<",\"engine_runs\":0}"<<std::endl;}
std::string shutdown_json(const UciShutdownResult&s){return "{\"reaped\":"+std::to_string(s.reaped)+",\"exit\":"+std::to_string(s.exit_code)+",\"signal\":"+std::to_string(s.signal)+",\"timed_out\":"+std::to_string(s.timed_out)+",\"driver_sigterm\":"+std::to_string(s.driver_sigterm)+",\"driver_sigkill\":"+std::to_string(s.driver_sigkill)+",\"quit_sent\":"+std::to_string(s.quit_sent)+",\"quit_to_exit_ms\":"+std::to_string(s.quit_to_exit_ms)+",\"shutdown_total_ms\":"+std::to_string(s.shutdown_total_ms)+",\"diagnostic_window\":"+std::to_string(s.diagnostic_window)+",\"natural_exit_observed_within_5s\":"+std::to_string(s.natural_exit_observed_within_5s)+",\"quit_write_budget_ms\":"+std::to_string(s.quit_write_budget_ms)+",\"natural_grace_ms\":"+std::to_string(s.natural_grace_ms)+",\"term_observation_ms\":"+std::to_string(s.term_observation_ms)+",\"kill_observation_ms\":"+std::to_string(s.kill_observation_ms)+",\"quit_write_begin_ms\":"+std::to_string(s.quit_write_begin_ms)+",\"quit_write_end_ms\":"+std::to_string(s.quit_write_end_ms)+",\"stdin_close_ms\":"+std::to_string(s.stdin_close_ms)+",\"reap_observed_ms\":"+std::to_string(s.reap_observed_ms)+",\"stdout_eof_observed_ms\":"+std::to_string(s.stdout_eof_observed_ms)+",\"stderr_eof_observed_ms\":"+std::to_string(s.stderr_eof_observed_ms)+",\"natural_deadline_ms\":"+std::to_string(s.natural_deadline_ms)+",\"sigterm_attempt_ms\":"+std::to_string(s.sigterm_attempt_ms)+",\"sigkill_attempt_ms\":"+std::to_string(s.sigkill_attempt_ms)+",\"sigterm_errno\":"+std::to_string(s.sigterm_errno)+",\"sigkill_errno\":"+std::to_string(s.sigkill_errno)+",\"stdout_eof_before_shutdown\":"+std::to_string(s.stdout_eof_before_shutdown)+",\"stderr_eof_before_shutdown\":"+std::to_string(s.stderr_eof_before_shutdown)+",\"diagnostic_fallback_used\":"+std::to_string(s.diagnostic_fallback_used)+",\"unreaped_child_pid\":"+std::to_string(s.unreaped_child_pid)+",\"error\":"+quote(s.error)+"}";}
int replay(const Inputs&d,const std::string&path){const auto begin=Clock::now(),hard=begin+std::chrono::seconds(410);std::unique_ptr<UciProcess> engine;Oracle oracle;oracle.reset();std::size_t published=0,index=0,sent=0,completed=0,matched=0,drifts=0,trace_begin=0;const Row*active=nullptr;Clock::time_point search_end{};std::string error;bool full_before_quit=false;UciShutdownResult shutdown;bool shutdown_observed=false;
 auto publish=[&](){if(engine){const auto&s=engine->transcript();std::cout<<s.substr(published);published=s.size();std::cout.flush();}};
 auto event=[&](const std::string&e){std::cout<<"EVENT {\"event\":"<<quote(e)<<",\"elapsed_ms\":"<<std::chrono::duration<double,std::milli>(Clock::now()-begin).count()<<"}"<<std::endl;};
 std::cout<<"CONFIG {\"kind\":"<<quote(d.kind)<<",\"engine\":"<<quote(path)<<",\"commands\":"<<d.commands.size()<<",\"searches\":"<<d.rows.size()<<",\"threads\":1,\"hash\":16,\"OwnBook\":false,\"HindsightDepth\":false,\"MateAlphaGuard\":false,\"replay_deadline_ms\":410000,\"search_deadline_ms\":15000,\"natural_quit_ms\":5000,\"soak_credit\":0,\"full_drift_policy\":\"stop-first\",\"cold_drift_policy\":\"report\"}"<<std::endl;
 try{engine=std::make_unique<UciProcess>(path,1,remaining(hard));publish();const auto init=stdin_lines(engine->transcript());require(init.size()==5&&std::equal(init.begin(),init.end(),d.commands.begin()),"constructor commands differ");sent=5;require(!diagnostic(engine->transcript()),"sanitizer_at_startup");
  for(std::size_t i=5;i<d.commands.size();++i){const auto&cmd=d.commands[i];const auto command_trace_begin=engine->transcript().size();require(i==sent,"input cursor");remaining(hard);if(cmd=="quit"){require(i+1==d.commands.size()&&active==nullptr&&completed==d.rows.size(),"early final quit");full_before_quit=true;break;}
   if(cmd.rfind("position ",0)==0){require(!active&&index<d.rows.size(),"position order");active=&d.rows[index++];require(active->first==i+1&&active->position==cmd,"position frame mismatch");oracle.position(*active);trace_begin=engine->transcript().size();search_end=std::min(hard,Clock::now()+std::chrono::seconds(15));std::cout<<"REPLAY_TRIGGER {\"ordinal\":"<<active->ordinal<<",\"source_ordinal\":"<<active->source<<",\"input_first\":"<<active->first<<",\"fen\":"<<quote(active->fen)<<",\"position\":"<<quote(active->position)<<",\"go\":"<<quote(active->go)<<"}"<<std::endl;engine->send(cmd,remaining(search_end));++sent;}
   else if(cmd.rfind("go ",0)==0){require(active&&cmd==active->go&&i+1==active->first+1,"go frame mismatch");engine->send(cmd,remaining(search_end));++sent;for(;;){const auto line=engine->line(remaining(search_end));if(line.rfind("bestmove",0)==0)break;}}
   else if(cmd=="isready"){engine->ready(remaining(active?search_end:hard));++sent;if(active){require(i+1==active->last,"barrier frame mismatch");const auto trace=engine->transcript().substr(trace_begin);publish();require(!diagnostic(trace),"sanitizer_diagnostic");const auto actual=validate(stdout_lines(trace),*active,oracle),expected=validate(active->expected,*active,oracle);++completed;const bool same=same_tuple(actual,expected,active->soft);if(same)++matched;else ++drifts;std::cout<<"REPLAY_CHECK {\"ordinal\":"<<active->ordinal<<",\"source_ordinal\":"<<active->source<<",\"search_completed_before_quit\":true,\"legal_move\":true,\"labels_valid\":true,\"tuple_equal\":"<<(same?"true":"false")<<",\"actual\":"<<tuple(actual)<<",\"expected\":"<<tuple(expected)<<"}"<<std::endl;active=nullptr;if(!same&&d.kind=="full")throw std::runtime_error("stable_tuple_drift");}}
   else if(cmd=="ucinewgame"){require(!active,"reset during search");oracle.reset();engine->send(cmd,remaining(hard));++sent;}
   else if(cmd.rfind("setoption ",0)==0){require(!active&&i<8,"unexpected option");engine->send(cmd,remaining(hard));++sent;}
   else throw std::runtime_error("unrecognized recorded command");
   publish();require(!diagnostic(engine->transcript().substr(command_trace_begin))&&!diagnostic(engine->stderr_output()),"sanitizer_diagnostic");
  }
 }catch(const UciStartupError&e){error=std::string(e.what()).substr(0,std::string(e.what()).find('\n'));shutdown=e.shutdown;shutdown_observed=true;std::cout<<"STARTUP_ERROR "<<quote(e.what())<<std::endl;}
 catch(const std::exception&e){error=std::string(e.what()).substr(0,std::string(e.what()).find('\n'));publish();}
 event("pre_quit_completion_frozen");if(engine){event("diagnostic_quit_begin");shutdown=engine->finish_diagnostic();shutdown_observed=true;publish();event("diagnostic_quit_end");}
 bool reports=engine?diagnostic(engine->transcript()+engine->stderr_output()):diagnostic(shutdown.transcript+shutdown.stderr_output);const bool normal=shutdown_observed&&shutdown.reaped&&shutdown.exit_code==0&&shutdown.signal==0&&!shutdown.timed_out&&!shutdown.driver_sigterm&&!shutdown.driver_sigkill&&shutdown.error.empty();if(engine){const auto actual=stdin_lines(engine->transcript());if(full_before_quit&&actual!=d.commands){if(error.empty())error="final_input_sequence_mismatch";full_before_quit=false;}std::cout<<"INPUT_SUMMARY {\"submitted_commands\":"<<actual.size()<<",\"exact_full_sequence\":"<<(actual==d.commands?"true":"false")<<"}"<<std::endl;}
 if(error.empty()&&reports)error="sanitizer_diagnostic";if(error.empty()&&!normal)error="shutdown_fault";if(error.empty()&&!shutdown.natural_exit_observed_within_5s)error="natural_exit_not_observed_within_5s";const bool success=full_before_quit&&completed==d.rows.size()&&error.empty()&&normal&&!reports&&shutdown.natural_exit_observed_within_5s;
 const auto complete_stderr=engine?engine->stderr_output():shutdown.stderr_output;std::cout<<"ENGINE_STDERR_JSON "<<quote(complete_stderr)<<std::endl;std::cout<<"ENGINE_STDERR_HEX "<<hex_bytes(complete_stderr)<<std::endl;std::cout<<"SHUTDOWN "<<shutdown_json(shutdown)<<std::endl;std::cout<<"RESULT {\"kind\":"<<quote(d.kind)<<",\"completed_searches_before_quit\":"<<completed<<",\"matched_searches\":"<<matched<<",\"tuple_drifts\":"<<drifts<<",\"all_recorded_searches_completed_before_quit\":"<<(full_before_quit?"true":"false")<<",\"shutdown_normal\":"<<(normal?"true":"false")<<",\"sanitizer_report\":"<<(reports?"true":"false")<<",\"error\":"<<quote(error)<<",\"diagnostic_success\":"<<(success?"true":"false")<<",\"soak_credit\":0,\"original_failure_unchanged\":true}"<<std::endl;return success?0:1;
}
}
int main(int argc,char**argv){try{if(argc==2&&std::string(argv[1])=="--unit-test"){unit();return 0;}if(argc==4&&std::string(argv[1])=="--offline"){offline(load(argv[2],argv[3]));return 0;}if(argc==5&&std::string(argv[1])=="--verify-trace"){verify_trace(load(argv[2],argv[3]),argv[4]);return 0;}if(argc==6&&std::string(argv[1])=="--run"&&std::string(argv[5])=="--diagnostic-authorized")return replay(load(argv[2],argv[3]),argv[4]);throw std::runtime_error("Use --unit-test, --offline INPUTS full|cold, --verify-trace INPUTS full|cold TRACE, or --run INPUTS full|cold ENGINE --diagnostic-authorized; no native authorization implied");}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
